{"file_path":"src/scanner.js","content":"import { fail } from './errors.js'

const BARE_NAME_RE = /[A-Za-z0-9_-]/
const HEX_RE = /[0-9a-fA-F]/

export class Cursor {
  constructor(line, lineNo) {
    this.line = line
    this.lineNo = lineNo
    this.pos = 0
  }

  get len() {
    return this.line.length
  }

  peek() {
    return this.pos < this.line.length ? this.line[this.pos] : undefined
  }

  atEnd() {
    return this.pos >= this.line.length
  }

  advance() {
    this.pos++
  }

  fail(reason) {
    fail(this.lineNo, reason)
  }

  skipWS() {
    while (!this.atEnd() && (this.line[this.pos] === ' ' || this.line[this.pos] === '\t')) {
      this.pos++
    }
  }

  // true if we are at end of significant content: end of line, or a comment start
  atCommentOrEnd() {
    if (this.atEnd()) return true
    const c = this.line[this.pos]
    return c === '#' || c === ';'
  }
}

export function parseBasicString(cur) {
  // assumes current char is '"'
  cur.advance()
  let result = ''
  for (;;) {
    if (cur.atEnd()) cur.fail('unterminated string')
    const c = cur.line[cur.pos]
    if (c === '"') {
      cur.advance()
      return result
    }
    if (c === '\\') {
      cur.advance()
      if (cur.atEnd()) cur.fail('unterminated string')
      const e = cur.line[cur.pos]
      switch (e) {
        case '"':
          result += '"'
          cur.advance()
          break
        case '\\':
          result += '\\'
          cur.advance()
          break
        case 'n':
          result += '\n'
          cur.advance()
          break
        case 't':
          result += '\t'
          cur.advance()
          break
        case 'r':
          result += '\r'
          cur.advance()
          break
        case '0':
          result += '\0'
          cur.advance()
          break
        case 'u': {
          cur.advance()
          const hex = cur.line.slice(cur.pos, cur.pos + 4)
          if (hex.length !== 4 || !/^[0-9a-fA-F]{4}$/.test(hex)) {
            cur.fail('invalid escape \\u')
          }
          result += String.fromCharCode(parseInt(hex, 16))
          cur.pos += 4
          break
        }
        default:
          cur.fail(`invalid escape \\${e}`)
      }
    } else {
      result += c
      cur.advance()
    }
  }
}

export function parseLiteralString(cur) {
  // assumes current char is '\''
  cur.advance()
  let start = cur.pos
  for (;;) {
    if (cur.atEnd()) cur.fail('unterminated string')
    const c = cur.line[cur.pos]
    if (c === "'") {
      const result = cur.line.slice(start, cur.pos)
      cur.advance()
      return result
    }
    cur.advance()
  }
}

export function parseName(cur) {
  const c = cur.peek()
  if (c === '"') return parseBasicString(cur)
  if (c === "'") return parseLiteralString(cur)
  const start = cur.pos
  while (!cur.atEnd() && BARE_NAME_RE.test(cur.line[cur.pos])) {
    cur.advance()
  }
  if (cur.pos === start) cur.fail('expected a name')
  return cur.line.slice(start, cur.pos)
}

export function parseDottedName(cur) {
  const segments = []
  for (;;) {
    segments.push(parseName(cur))
    cur.skipWS()
    if (cur.peek() === '.') {
      cur.advance()
      cur.skipWS()
      continue
    }
    break
  }
  return segments
}

const DIGITS_RE = '[0-9]+(?:_[0-9]+)*'
const INT_RE = new RegExp(`^[+-]?${DIGITS_RE}$`)
const FLOAT_RE = new RegExp(
  `^[+-]?${DIGITS_RE}(?:(?:\\.${DIGITS_RE})(?:[eE][+-]?${DIGITS_RE})?|(?:[eE][+-]?${DIGITS_RE}))$`
)

const BAREWORD_STOP = new Set([' ', '\t', ',', ']', '}', ';'])

function scanBareword(cur) {
  const start = cur.pos
  while (!cur.atEnd() && !BAREWORD_STOP.has(cur.line[cur.pos])) {
    cur.advance()
  }
  return cur.line.slice(start, cur.pos)
}

export function parseValue(cur, prefix) {
  if (cur.atEnd() || cur.peek() === '#' || cur.peek() === ';') {
    cur.fail('expected a value')
  }
  const c = cur.peek()
  if (c === '"') {
    return { kind: 'string', value: parseBasicString(cur) }
  }
  if (c === "'") {
    return { kind: 'string', value: parseLiteralString(cur) }
  }
  if (c === '[') {
    return parseArrayValue(cur, prefix)
  }
  if (c === '{') {
    return parseInlineTable(cur, prefix)
  }
  const token = scanBareword(cur)
  if (token === '') {
    cur.fail('expected a value')
  }
  if (token === 'true') return { kind: 'boolean', value: true }
  if (token === 'false') return { kind: 'boolean', value: false }
  if (INT_RE.test(token)) {
    const cleaned = token.replace(/_/g, '')
    return { kind: 'integer', value: Number(cleaned) }
  }
  if (FLOAT_RE.test(token)) {
    const cleaned = token.replace(/_/g, '')
    return { kind: 'float', value: Number(cleaned) }
  }
  cur.fail(`invalid value ${token}`)
}

function parseArrayValue(cur, prefix) {
  cur.advance() // consume '['
  const items = []
  cur.skipWS()
  if (cur.peek() === ']') {
    cur.advance()
    return { kind: 'array', items }
  }
  for (;;) {
    if (cur.atEnd()) cur.fail('unterminated array')
    const value = parseValue(cur, prefix)
    items.push(value)
    cur.skipWS()
    if (cur.atEnd()) cur.fail('unterminated array')
    const c = cur.peek()
    if (c === ',') {
      cur.advance()
      cur.skipWS()
      if (cur.peek() === ']') {
        cur.advance()
        return { kind: 'array', items }
      }
      continue
    }
    if (c === ']') {
      cur.advance()
      return { kind: 'array', items }
    }
    cur.fail('unterminated array')
  }
}

export function parseInlineTable(cur, prefix) {
  cur.advance() // consume '{'
  const table = { kind: 'table', entries: new Map(), headerMade: false }
  cur.skipWS()
  if (cur.peek() === '}') {
    cur.advance()
    return table
  }
  for (;;) {
    if (cur.atEnd()) cur.fail('unterminated inline table')
    const segments = parseDottedName(cur)
    cur.skipWS()
    if (cur.peek() !== '=') cur.fail('expected = in an inline table')
    cur.advance()
    cur.skipWS()
    const value = parseValue(cur, prefix.concat(segments))
    assignInto(table, segments, value, cur.lineNo, prefix)
    cur.skipWS()
    if (cur.atEnd()) cur.fail('unterminated inline table')
    const c = cur.peek()
    if (c === '}') {
      cur.advance()
      return table
    }
    if (c === ',') {
      cur.advance()
      cur.skipWS()
      continue
    }
    cur.fail('unterminated inline table')
  }
}

// imported here to avoid a cycle at module-eval time; tree.js does not import scanner.js
import { assignInto } from './tree.js'
"}

