// Parser for the configuration document format described in the task.
//
// Produces a tree of tagged nodes:
//   { type: 'table', map: Map<string, Node>, path: string[], headered: bool }
//   { type: 'array-table', items: Node[] }        // items are 'table' nodes
//   { type: 'array', items: Node[] }
//   { type: 'string', value: string }
//   { type: 'integer', value: BigInt }
//   { type: 'float', value: number }
//   { type: 'boolean', value: boolean }

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.isParseError = true
    this.line = line
    this.reason = reason
  }
}

function mkErr(line, reason) {
  return new ParseError(line, reason)
}

function renderPath(path) {
  return path.join('.')
}

function compareCodePoints(a, b) {
  const ca = Array.from(a)
  const cb = Array.from(b)
  const len = Math.min(ca.length, cb.length)
  for (let i = 0; i < len; i++) {
    const pa = ca[i].codePointAt(0)
    const pb = cb[i].codePointAt(0)
    if (pa !== pb) return pa - pb
  }
  return ca.length - cb.length
}

class LineParser {
  constructor(line, lineNo) {
    this.line = line
    this.pos = 0
    this.lineNo = lineNo
  }

  atEnd() {
    return this.pos >= this.line.length
  }

  peek() {
    return this.line[this.pos]
  }

  skipWS() {
    while (!this.atEnd() && (this.peek() === ' ' || this.peek() === '\t')) this.pos++
  }

  skipWSAndComment() {
    this.skipWS()
    if (!this.atEnd() && (this.peek() === '#' || this.peek() === ';')) {
