          lp.pos++
          break
        case 'n':
          result += '\n'
          lp.pos++
          break
        case 't':
          result += '\t'
          lp.pos++
          break
        case 'r':
          result += '\r'
          lp.pos++
          break
        case '0':
          result += '\0'
          lp.pos++
          break
        case 'u': {
          const hexStart = lp.pos + 1
          if (hexStart + 4 > lp.line.length) throw mkErr(lp.lineNo, 'unterminated string')
          const hex = lp.line.slice(hexStart, hexStart + 4)
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) throw mkErr(lp.lineNo, 'invalid escape \\u')
          result += String.fromCharCode(parseInt(hex, 16))
          lp.pos = hexStart + 4
          break
        }
        default:
          throw mkErr(lp.lineNo, `invalid escape \\${e}`)
      }
      continue
    }
    result += c
    lp.pos++
  }
}

function parseLiteralString(lp) {
  // assumes lp.peek() === "'"
  lp.pos++
  let result = ''
  while (true) {
    if (lp.atEnd()) throw mkErr(lp.lineNo, 'unterminated string')
    const c = lp.line[lp.pos]
    if (c === "'") {
      lp.pos++
      return result
    }
    result += c
    lp.pos++
  }
