  if (FLOAT_RE.test(word)) return { type: 'float', value: Number(word.replace(/_/g, '')) }
  throw mkErr(lp.lineNo, `invalid value ${word}`)
}

function parseArray(lp) {
  lp.pos++ // consume '['
  const items = []
  lp.skipWSAndComment()
  if (lp.atEnd()) throw mkErr(lp.lineNo, 'unterminated array')
  if (lp.peek() === ']') {
