  }
  return { type: 'array', items }
}

function assignDotted(container, names, value, lineNo) {
  let t = container
  let path = container.path
  for (let i = 0; i < names.length - 1; i++) {
    const name = names[i]
    path = path.concat(name)
    const entry = t.map.get(name)
    if (entry === undefined) {
      const nt = { type: 'table', map: new Map(), path, headered: false }
      t.map.set(name, nt)
      t = nt
    } else if (entry.type === 'table') {
      t = entry
    } else if (entry.type === 'array-table') {
      t = entry.items[entry.items.length - 1]
    } else {
      throw mkErr(lineNo, `${renderPath(path)} is not a table`)
    }
  }
  const last = names[names.length - 1]
  const finalPath = path.concat(last)
  if (t.map.has(last)) {
    throw mkErr(lineNo, `key ${renderPath(finalPath)} is defined twice`)
  }
  t.map.set(last, value)
}

function parseInlineTable(lp, pathPrefix) {
  lp.pos++ // consume '{'
  const table = { type: 'table', map: new Map(), path: pathPrefix, headered: true }
  lp.skipWSAndComment()
  if (lp.atEnd()) throw mkErr(lp.lineNo, 'unterminated inline table')
  if (lp.peek() === '}') {
    lp.pos++
    return table
  }
  while (true) {
    lp.skipWSAndComment()
    if (lp.atEnd()) throw mkErr(lp.lineNo, 'unterminated inline table')
    const names = parseDottedName(lp)
    lp.skipWSAndComment()
    if (lp.atEnd() || lp.peek() !== '=') throw mkErr(lp.lineNo, 'expected = in an inline table')
    lp.pos++
    lp.skipWSAndComment()
    if (lp.atEnd()) throw mkErr(lp.lineNo, 'expected a value')
    const fullPath = pathPrefix.concat(names)
    const value = parseValue(lp, fullPath)
    assignDotted(table, names, value, lp.lineNo)
    lp.skipWSAndComment()
    if (lp.atEnd()) throw mkErr(lp.lineNo, 'unterminated inline table')
    if (lp.peek() === ',') {
      lp.pos++
      continue
    }
    if (lp.peek() === '}') {
      lp.pos++
      break
    }
    throw mkErr(lp.lineNo, 'unterminated inline table')
  }
  return table
}

function walkIntermediateForHeader(root, names, lineNo) {
  let t = root
  let path = []
  for (let i = 0; i < names.length - 1; i++) {
    const name = names[i]
    path = path.concat(name)
    const entry = t.map.get(name)
    if (entry === undefined) {
      const nt = { type: 'table', map: new Map(), path, headered: false }
      t.map.set(name, nt)
      t = nt
    } else if (entry.type === 'table') {
      t = entry
    } else if (entry.type === 'array-table') {
      t = entry.items[entry.items.length - 1]
    } else {
      throw mkErr(lineNo, `${renderPath(path)} is not a table`)
    }
  }
  return { table: t, path }
}

function handleHeader(state, names, isArray, lineNo) {
  const { table, path } = walkIntermediateForHeader(state.root, names, lineNo)
  const last = names[names.length - 1]
  const finalPath = path.concat(last)
  const entry = table.map.get(last)
  if (!isArray) {
    if (entry === undefined) {
      const nt = { type: 'table', map: new Map(), path: finalPath, headered: true }
      table.map.set(last, nt)
      state.current = nt
    } else if (entry.type === 'table') {
      if (entry.headered) throw mkErr(lineNo, `table ${renderPath(finalPath)} is defined twice`)
      entry.headered = true
      state.current = entry
    } else {
      throw mkErr(lineNo, `${renderPath(finalPath)} is not a table`)
    }
  } else {
    if (entry === undefined) {
      const at = { type: 'array-table', items: [] }
      table.map.set(last, at)
      const item = { type: 'table', map: new Map(), path: finalPath, headered: false }
      at.items.push(item)
      state.current = item
    } else if (entry.type === 'array-table') {
      const item = { type: 'table', map: new Map(), path: finalPath, headered: false }
      entry.items.push(item)
      state.current = item
    } else {
      throw mkErr(lineNo, `${renderPath(finalPath)} is not an array of tables`)
    }
  }
}

