// Path segments used both for error messages and for the `keys` output.
// Each segment is either { kind: 'key', value: <decoded key text> }
// or { kind: 'index', value: <integer index> }.

export function keySeg(value) {
  return { kind: 'key', value }
}

export function indexSeg(value) {
  return { kind: 'index', value }
}

export function formatPath(segments) {
  let out = ''
  for (const seg of segments) {
    if (seg.kind === 'index') {
      out += `[${seg.value}]`
    } else {
      out += out === '' ? seg.value : `.${seg.value}`
    }
  }
  return out
}

export function compareCodepoints(a, b) {
  const ac = Array.from(a)
  const bc = Array.from(b)
  const len = Math.min(ac.length, bc.length)
  for (let i = 0; i < len; i++) {
    const ca = ac[i].codePointAt(0)
    const cb = bc[i].codePointAt(0)
    if (ca !== cb) return ca - cb
  }
  return ac.length - bc.length
}

