import { compareCodePoints } from './parser.js'

function typeOf(node) {
  switch (node.type) {
    case 'table':
      return 'table'
    case 'array-table':
    case 'array':
      return 'array'
    case 'string':
      return 'string'
    case 'integer':
      return 'integer'
    case 'float':
      return 'float'
    case 'boolean':
      return 'boolean'
    default:
      throw new Error(`unknown node type ${node.type}`)
  }
}

function sortedKeys(map) {
  return [...map.keys()].sort(compareCodePoints)
}

function jsonStringifyValue(node, indent) {
  const pad = '  '.repeat(indent)
  const padChild = '  '.repeat(indent + 1)
  switch (node.type) {
    case 'table': {
      const keys = sortedKeys(node.map)
      if (keys.length === 0) return '{}'
      const parts = keys.map(
        (k) => `${padChild}${JSON.stringify(k)}: ${jsonStringifyValue(node.map.get(k), indent + 1)}`
      )
      return '{\n' + parts.join(',\n') + '\n' + pad + '}'
    }
    case 'array-table':
    case 'array': {
      const items = node.items
      if (items.length === 0) return '[]'
      const parts = items.map((it) => padChild + jsonStringifyValue(it, indent + 1))
      return '[\n' + parts.join(',\n') + '\n' + pad + ']'
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'integer':
      return node.value.toString()
    case 'float':
      return String(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    default:
      throw new Error(`unknown node type ${node.type}`)
  }
}

export function renderJSON(root) {
  return jsonStringifyValue(root, 0) + '\n'
}

function collectKeys(node, path, lines) {
  if (node.type === 'table') {
    for (const k of sortedKeys(node.map)) {
      const child = node.map.get(k)
      const childPath = path ? `${path}.${k}` : k
      lines.push(`${childPath} ${typeOf(child)}`)
      collectKeys(child, childPath, lines)
    }
  } else if (node.type === 'array-table' || node.type === 'array') {
    node.items.forEach((item, i) => {
      const childPath = `${path}[${i}]`
      lines.push(`${childPath} ${typeOf(item)}`)
      collectKeys(item, childPath, lines)
    })
  }
}

export function renderKeys(root) {
  const lines = []
  collectKeys(root, '', lines)
  return lines.length === 0 ? '' : lines.join('\n') + '\n'
}

